create table if not exists public.academy_cohorts (id uuid primary key default gen_random_uuid(),course_id uuid not null references public.academy_courses(id) on delete cascade,name text not null,starts_at timestamptz,ends_at timestamptz,capacity integer,status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.academy_instructors (id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id),display_name text not null,bio text,expertise text[],is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.academy_cohort_instructors (cohort_id uuid references public.academy_cohorts(id) on delete cascade,instructor_id uuid references public.academy_instructors(id) on delete cascade,role text not null default 'instructor',primary key(cohort_id,instructor_id));
create table if not exists public.academy_assignments (id uuid primary key default gen_random_uuid(),course_id uuid not null references public.academy_courses(id) on delete cascade,cohort_id uuid references public.academy_cohorts(id) on delete cascade,title text not null,instructions text,due_at timestamptz,max_score numeric not null default 100,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.academy_assignment_submissions (id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.academy_assignments(id) on delete cascade,enrollment_id uuid not null references public.academy_enrollments(id) on delete cascade,submission_url text,submission_text text,submitted_at timestamptz,status text not null default 'draft',score numeric,feedback text,graded_at timestamptz,graded_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(assignment_id,enrollment_id));
alter table public.academy_cohorts enable row level security;alter table public.academy_instructors enable row level security;alter table public.academy_cohort_instructors enable row level security;alter table public.academy_assignments enable row level security;alter table public.academy_assignment_submissions enable row level security;
create policy "academy cohorts super admin manage" on public.academy_cohorts for all to authenticated using (private.is_admin(array['super_admin']::public.user_role[])) with check (private.is_admin(array['super_admin']::public.user_role[]));create policy "academy instructors super admin manage" on public.academy_instructors for all to authenticated using (private.is_admin(array['super_admin']::public.user_role[])) with check (private.is_admin(array['super_admin']::public.user_role[]));create policy "academy cohort instructors super admin manage" on public.academy_cohort_instructors for all to authenticated using (private.is_admin(array['super_admin']::public.user_role[])) with check (private.is_admin(array['super_admin']::public.user_role[]));create policy "academy assignments super admin manage" on public.academy_assignments for all to authenticated using (private.is_admin(array['super_admin']::public.user_role[])) with check (private.is_admin(array['super_admin']::public.user_role[]));create policy "academy submissions super admin manage" on public.academy_assignment_submissions for all to authenticated using (private.is_admin(array['super_admin']::public.user_role[])) with check (private.is_admin(array['super_admin']::public.user_role[]));create policy "academy published assignments authenticated read" on public.academy_assignments for select to authenticated using (is_published);